/// The rules to try for the character at the current position.
///
/// `None` for anything outside `A`–`Z`, which upstream skips without consuming
/// — the same answer, since a character with no group has no spelling either way.
pub fn group(letter: char) -> Option<&'static [Rule]> {
    match letter {
        'A' => Some(&RULES[0..33]),
        'B' => Some(&RULES[33..39]),
        'C' => Some(&RULES[39..50]),
        'D' => Some(&RULES[50..60]),
        'E' => Some(&RULES[60..95]),
        'F' => Some(&RULES[95..97]),
        'G' => Some(&RULES[97..107]),
        'H' => Some(&RULES[107..113]),
        'I' => Some(&RULES[113..141]),
        'J' => Some(&RULES[141..142]),
        'K' => Some(&RULES[142..144]),
        'L' => Some(&RULES[144..149]),
        'M' => Some(&RULES[149..151]),
        'N' => Some(&RULES[151..159]),
        'O' => Some(&RULES[159..207]),
        'P' => Some(&RULES[207..212]),
        'Q' => Some(&RULES[212..215]),
        'R' => Some(&RULES[215..217]),
        'S' => Some(&RULES[217..240]),
        'T' => Some(&RULES[240..266]),
        'U' => Some(&RULES[266..281]),
        'V' => Some(&RULES[281..283]),
        'W' => Some(&RULES[283..295]),
        'X' => Some(&RULES[295..297]),
        'Y' => Some(&RULES[297..308]),
        'Z' => Some(&RULES[308..309]),
        _ => None,
    }
}
